38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.controller.CityOwnerLimitExceededException;
41	import org.springframework.samples.petclinic.rest.controller.DailyOwnerLimitExceededException;
42	import org.springframework.samples.petclinic.rest.controller.DuplicateHouseholdException;
43	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
44	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
